import { test, expect } from '@playwright/test';

test.describe('Form Validation - Required Fields Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page with a form that has required fields
    // Using a sample form URL - adjust based on your application
    await page.goto('about:blank');

    // Create a simple form with required fields for testing
    await page.setContent(`
      <form id="testForm">
        <div>
          <label for="firstName">First Name *</label>
          <input id="firstName" name="firstName" type="text" required />
          <span class="error-message" style="display:none; color:red;">This field is required</span>
        </div>
        <div>
          <label for="email">Email *</label>
          <input id="email" name="email" type="email" required />
          <span class="error-message" style="display:none; color:red;">This field is required</span>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message"></textarea>
        </div>
        <button type="submit">Submit</button>
      </form>
      <style>
        input:invalid, textarea:invalid {
          border: 2px solid red;
          background-color: #ffe6e6;
        }
        input:valid, textarea:valid {
          border: 2px solid green;
        }
      </style>
      <script>
        document.getElementById('testForm').addEventListener('submit', function(e) {
          e.preventDefault();
          const inputs = this.querySelectorAll('[required]');
          inputs.forEach(input => {
            const errorMsg = input.parentElement.querySelector('.error-message');
            if (!input.value.trim()) {
              input.classList.add('field-error');
              if (errorMsg) {
                errorMsg.style.display = 'block';
              }
            } else {
              input.classList.remove('field-error');
              if (errorMsg) {
                errorMsg.style.display = 'none';
              }
            }
          });
        });
      </script>
    `);
  });

  test('should highlight required fields with red border when submitting empty form', async ({ page }) => {
    // Get the submit button and click it without filling any fields
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify that the first name field is highlighted with error styling
    const firstNameInput = page.getByLabel('First Name *');
    await expect(firstNameInput).toHaveCSS('border', /red/);

    // Verify that the email field is highlighted with error styling
    const emailInput = page.getByLabel('Email *');
    await expect(emailInput).toHaveCSS('border', /red/);

    // Verify error messages are displayed for required fields
    const errorMessages = page.locator('.error-message');
    const visibleErrors = await errorMessages.filter({ hasNot: page.locator('css=[style*="display: none"]') }).count();
    expect(visibleErrors).toBeGreaterThanOrEqual(2);
  });

  test('should not highlight optional fields when submitting empty form', async ({ page }) => {
    // Get the submit button and click it without filling any fields
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify that the optional message field does not have error styling
    const messageTextarea = page.getByLabel('Message');
    const borderStyle = await messageTextarea.evaluate((el: HTMLElement) => {
      return window.getComputedStyle(el).border;
    });

    // Optional field should not have red border
    expect(borderStyle).not.toContain('red');
  });

  test('should remove highlighting when required fields are filled', async ({ page }) => {
    // Submit empty form first to trigger validation
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify fields are highlighted
    const firstNameInput = page.getByLabel('First Name *');
    await expect(firstNameInput).toHaveCSS('border', /red/);

    // Fill in the required fields
    await firstNameInput.fill('John');
    const emailInput = page.getByLabel('Email *');
    await emailInput.fill('john@example.com');

    // Submit the form again
    await submitButton.click();

    // Verify that error messages are no longer visible for filled fields
    const errorMessages = page.locator('.error-message');
    const visibleErrors = await errorMessages.filter({ hasNot: page.locator('css=[style*="display: none"]') }).count();
    expect(visibleErrors).toBe(0);
  });

  test('should highlight only the specific required field that is empty', async ({ page }) => {
    // Fill in the first name but leave email empty
    const firstNameInput = page.getByLabel('First Name *');
    await firstNameInput.fill('John');

    // Submit the form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify that first name field does not have error styling
    const firstNameBorder = await firstNameInput.evaluate((el: HTMLElement) => {
      return window.getComputedStyle(el).border;
    });
    expect(firstNameBorder).not.toContain('red');

    // Verify that email field is highlighted with error styling
    const emailInput = page.getByLabel('Email *');
    await expect(emailInput).toHaveCSS('border', /red/);
  });
});
